<script setup lang="ts">
import { ref } from 'vue'
import type { RecordedSession } from '../simulation/sessions'
defineProps<{ mode: 'live' | 'recording' | 'playing' | 'paused'; sessions: RecordedSession[]; selected: string; name: string; position: number; duration: number; events: number; speed: number; ignored: number; error: string }>()
const emit = defineEmits<{ record: []; stop: []; play: []; pause: []; live: []; seek: [value: number]; export: []; import: [file: File]; select: [id: string]; name: [value: string]; speed: [value: number] }>()
const file = ref<HTMLInputElement>()
function importFile(event: Event) { const input = event.target as HTMLInputElement; const selected = input.files?.[0]; if (selected) emit('import', selected); input.value = '' }
function time(milliseconds: number) { const seconds = Math.max(0, milliseconds) / 1000; return `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toFixed(1).padStart(4, '0')}` }
</script>

<template>
  <section class="session-recorder" aria-label="Session recording and replay" :class="{ recording: mode === 'recording', replaying: mode === 'playing' || mode === 'paused' }">
    <div class="session-summary"><span class="session-indicator" :class="mode"></span><strong>{{ mode === 'recording' ? 'Recording session' : mode === 'playing' ? 'Playing session' : mode === 'paused' ? 'Replay paused' : 'Sessions' }}</strong><span v-if="mode !== 'live'" class="session-count">{{ events }} events · {{ time(mode === 'recording' ? duration : position) }}{{ mode === 'recording' ? '' : ` / ${time(duration)}` }}</span><span v-else class="session-help">Record both serial lines and replay the scene</span></div>
    <div class="session-actions">
      <template v-if="mode === 'live'"><input :value="name" maxlength="80" aria-label="Session name" placeholder="Session name" @input="emit('name', ($event.target as HTMLInputElement).value)" /><button class="button secondary" @click="emit('record')">● Record</button><select :value="selected" aria-label="Saved session" title="The 10 most recent recordings are saved in this browser. Export JSON to keep or share a session." :disabled="!sessions.length" @change="emit('select', ($event.target as HTMLSelectElement).value)"><option v-if="!sessions.length" value="">No recordings yet</option><option v-for="session in sessions" :key="session.id" :value="session.id">{{ session.name }} · {{ time(session.duration) }}</option></select><button class="button primary" :disabled="!selected" @click="emit('play')">▶ Replay</button><button class="text-button" :disabled="!selected" @click="emit('export')">Export</button><button class="text-button" @click="file?.click()">Import</button></template>
      <template v-else-if="mode === 'recording'"><span class="session-help">{{ name }} · Starting state and byte timing included</span><button class="button danger-outline" @click="emit('stop')">■ Stop &amp; save</button></template>
      <template v-else><button class="button secondary" @click="mode === 'playing' ? emit('pause') : emit('play')">{{ mode === 'playing' ? 'Ⅱ Pause' : '▶ Play' }}</button><button class="text-button" aria-label="Restart replay" @click="emit('seek', 0)">↶ Restart</button><label class="replay-speed">Speed<select :value="speed" aria-label="Replay speed" @change="emit('speed', Number(($event.target as HTMLSelectElement).value))"><option :value="0.25">0.25×</option><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></label><button class="button primary" @click="emit('live')">Return to live</button></template>
    </div>
    <div v-if="mode === 'playing' || mode === 'paused'" class="session-timeline"><input :value="position" type="range" min="0" :max="Math.max(1, duration)" step="1" aria-label="Replay timeline" :aria-valuetext="`${time(position)} of ${time(duration)}`" @input="emit('seek', Number(($event.target as HTMLInputElement).value))" /><span>Live serial input is excluded from replay{{ ignored ? ` · ${ignored} incoming chunks skipped` : '' }}. Return to live restores your previous setup.</span></div>
    <p v-if="error" class="error-message" role="alert">{{ error }}</p>
    <input ref="file" class="session-file" type="file" accept="application/json,.json" aria-label="Import IRIS session file" @change="importFile" />
  </section>
</template>

<style scoped>
.session-recorder{margin:14px 28px 0;padding:12px 16px;border:1px solid #2d414e;border-radius:8px;background:#101d27;display:flex;align-items:center;gap:12px 20px;flex-wrap:wrap}.session-summary{display:flex;align-items:center;gap:10px;min-width:0}.session-summary strong{font-size:12px;white-space:nowrap}.session-help,.session-count{font-size:10px;color:#829eae}.session-count{font-family:var(--mono)}.session-indicator{width:7px;height:7px;border-radius:50%;background:#5e7888}.session-indicator.recording{background:#ff716d;box-shadow:0 0 9px #ff716d66}.session-indicator.playing,.session-indicator.paused{background:var(--mint)}.session-actions{margin-left:auto;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.session-actions input,.session-actions select{font-size:11px;padding:7px 9px;max-width:220px}.session-actions input{width:150px}.session-actions .button{font-size:11px;padding:8px 12px}.session-actions .text-button{font-size:10px}.replay-speed{display:flex;align-items:center;gap:7px;font-size:10px;color:#89a5b4}.replay-speed select{width:75px}.session-timeline{flex-basis:100%;display:flex;align-items:center;gap:18px}.session-timeline input{flex:1;min-width:120px;accent-color:var(--mint)}.session-timeline span{font-size:10px;color:#91aebd;max-width:470px;line-height:1.6}.session-file{display:none}.session-recorder.recording{border-color:#79504d}.session-recorder.replaying{border-color:#427c70}.error-message{flex-basis:100%;margin:0;font-size:11px}@media(max-width:1000px){.session-actions{margin-left:0}.session-help{display:none}.session-timeline{flex-wrap:wrap;gap:5px}.session-timeline span{max-width:none;flex-basis:100%}}@media(max-width:700px){.session-recorder{margin:12px 14px 0}.session-actions input{width:130px}.session-actions select{max-width:170px}}
</style>
